import{NextResponse}from"next/server";import{prisma}from"@/lib/prisma";import{createExternalCost}from"@/lib/external";export async function GET(){return NextResponse.json(await prisma.externalLinkedCost.findMany({include:{item:true,externalTrade:true},orderBy:{costDate:"desc"}}))}export async function POST(r:Request){try{const b=await r.json(),x=await prisma.$transaction(tx=>createExternalCost(tx,b));return NextResponse.json(x,{status:201})}catch(e){return NextResponse.json({error:e instanceof Error?e.message:"تعذر الحفظ"},{status:400})}}
